package innertube

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"
	"testing"
)

const okResponse = `{
 "responseContext": {"visitorData": "VISITOR"},
 "playabilityStatus": {"status": "OK"},
 "videoDetails": {"videoId": "KGC7E3XYZ1M", "title": "The Thin Ice", "author": "PINK FLOYD - Topic", "lengthSeconds": "147",
  "shortDescription": "Provided to YouTube by Parlophone UK\n\nThe Thin Ice · Pink Floyd · Pink Floyd\n\nThe Wall\n\n℗ 1979 Pink Floyd Music Ltd.\n\nReleased on: 1979-11-30\n\nAuto-generated by YouTube.",
  "thumbnail": {"thumbnails": [{"url": "https://i.ytimg.com/vi/x/default.jpg", "width": 120, "height": 90}, {"url": "https://i.ytimg.com/vi/x/maxres.jpg", "width": 1280, "height": 720}]}},
 "streamingData": {"adaptiveFormats": [
  {"itag": 137, "url": "https://rr1---sn-x.googlevideo.com/videoplayback?itag=137", "mimeType": "video/mp4; codecs=\"avc1\"", "bitrate": 4000000, "contentLength": "9"},
  {"itag": 140, "url": "https://rr1---sn-x.googlevideo.com/videoplayback?itag=140", "mimeType": "audio/mp4; codecs=\"mp4a.40.2\"", "bitrate": 130000, "contentLength": "2400000"},
  {"itag": 251, "url": "https://rr1---sn-x.googlevideo.com/videoplayback?itag=251", "mimeType": "audio/webm; codecs=\"opus\"", "bitrate": 141000, "contentLength": "2500000"},
  {"itag": 250, "signatureCipher": "s=abc&url=https%3A%2F%2Frr1.googlevideo.com", "mimeType": "audio/webm; codecs=\"opus\"", "bitrate": 70000},
  {"itag": 249, "url": "https://evil.example.com/videoplayback", "mimeType": "audio/webm; codecs=\"opus\"", "bitrate": 50000, "contentLength": "1"}
 ]}
}`

func TestParseOK(t *testing.T) {
	v, err := parse([]byte(okResponse))
	if err != nil {
		t.Fatal(err)
	}
	if v.VisitorData != "VISITOR" || v.Title != "The Thin Ice" || v.Duration != 147 || !strings.HasSuffix(v.Thumbnail, "maxres.jpg") {
		t.Errorf("details: %+v", v)
	}
	// video, ciphered and off-site streams are dropped
	if len(v.Audio) != 2 {
		t.Fatalf("audio streams: %+v", v.Audio)
	}
	f, ok := BestAudio(v, []int{774, 251}, "opus")
	if !ok || f.Itag != 251 || f.Codec() != "opus" || f.Ext() != "webm" || f.ContentLength != 2500000 {
		t.Errorf("opus pick: %+v", f)
	}
	f, _ = BestAudio(v, []int{141, 140}, "mp4a")
	if f.Itag != 140 || f.Ext() != "m4a" {
		t.Errorf("aac pick: %+v", f)
	}
	f, _ = BestAudio(v, nil, "")
	if f.Itag != 251 {
		t.Errorf("highest bitrate: %+v", f)
	}
}

func TestParseRefusals(t *testing.T) {
	_, err := parse([]byte(`{"responseContext":{"visitorData":"V"},"playabilityStatus":{"status":"LOGIN_REQUIRED","reason":"Sign in to confirm you’re not a bot"}}`))
	var up *Unplayable
	if !errors.As(err, &up) || up.Status != "LOGIN_REQUIRED" {
		t.Fatalf("got %v", err)
	}
	if _, err := parse([]byte(`{"playabilityStatus":{"status":"OK"},"streamingData":{"adaptiveFormats":[{"itag":251,"signatureCipher":"s=x","mimeType":"audio/webm"}]}}`)); !errors.Is(err, ErrNoAudio) {
		t.Fatalf("cipher only: %v", err)
	}
	if _, err := parse([]byte(`not json`)); err == nil {
		t.Fatal("garbage accepted")
	}
}

func TestParseMusic(t *testing.T) {
	m, ok := ParseMusic("Provided to YouTube by DistroKid\n\nWet Hands · C418\n\nMinecraft - Volume Alpha\n\n℗ 2011 C418\n\nReleased on: 2011-03-04\n\nAuto-generated by YouTube.")
	if !ok || m.Title != "Wet Hands" || len(m.Artists) != 1 || m.Artists[0] != "C418" || m.Album != "Minecraft - Volume Alpha" || m.Date != "2011-03-04" || m.Year != 2011 {
		t.Errorf("%+v", m)
	}
	m, ok = ParseMusic("Provided to YouTube by X\n\nSong · A · B · a\n\n℗ 2020 X")
	if !ok || m.Album != "" || m.Year != 2020 || len(m.Artists) != 2 {
		t.Errorf("no album / dup artist: %+v", m)
	}
	if _, ok := ParseMusic("Official video for my song"); ok {
		t.Error("an ordinary description is not music metadata")
	}
}

type roundTrip func(*http.Request) (*http.Response, error)

func (f roundTrip) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

func TestPlayerRequest(t *testing.T) {
	var got struct {
		Context struct {
			Client map[string]any `json:"client"`
		} `json:"context"`
		VideoID        string `json:"videoId"`
		ContentCheckOk bool   `json:"contentCheckOk"`
	}
	var hdr http.Header
	hc := &http.Client{Transport: roundTrip(func(r *http.Request) (*http.Response, error) {
		hdr = r.Header
		if r.URL.Host != "www.youtube.com" || r.URL.Path != "/youtubei/v1/player" {
			t.Errorf("endpoint %s", r.URL)
		}
		b, _ := io.ReadAll(r.Body)
		json.Unmarshal(b, &got)
		return &http.Response{StatusCode: 200, Body: io.NopCloser(strings.NewReader(okResponse)), Header: http.Header{}}, nil
	})}
	c := Clients[0]
	v, err := Player(context.Background(), hc, c, "KGC7E3XYZ1M", "VIS")
	if err != nil {
		t.Fatal(err)
	}
	if got.VideoID != "KGC7E3XYZ1M" || !got.ContentCheckOk || got.Context.Client["clientName"] != c.Name || got.Context.Client["visitorData"] != "VIS" {
		t.Errorf("body: %+v", got)
	}
	if hdr.Get("X-YouTube-Client-Name") != "101" || hdr.Get("X-Goog-Visitor-Id") != "VIS" || hdr.Get("User-Agent") != c.UserAgent {
		t.Errorf("headers: %v", hdr)
	}
	if v.UserAgent != c.UserAgent {
		t.Error("the stream must be fetched with the client's user agent")
	}
	if _, err := Player(context.Background(), hc, c, "../etc", ""); err == nil {
		t.Error("bad id accepted")
	}
	hc429 := &http.Client{Transport: roundTrip(func(*http.Request) (*http.Response, error) {
		return &http.Response{StatusCode: 429, Body: io.NopCloser(strings.NewReader("")), Header: http.Header{}}, nil
	})}
	var he *HTTPError
	if _, err := Player(context.Background(), hc429, c, "KGC7E3XYZ1M", ""); !errors.As(err, &he) || he.Status != 429 {
		t.Errorf("429: %v", err)
	}
}
